BEGIN;
DELETE FROM master_bidv_connector_service.bank_requests m
 USING (VALUES (123456789::bigint, 987654321::bigint)) AS v(old_gid, new_gid)
 WHERE m."_gpay_id" = v.old_gid::bigint
   AND EXISTS (SELECT 1 FROM master_bidv_connector_service.bank_requests m2 WHERE m2."_gpay_id" = v.new_gid::bigint);
UPDATE master_bidv_connector_service.bank_requests m
   SET "_gpay_id" = v.new_gid::bigint
  FROM (VALUES (123456789::bigint, 987654321::bigint)) AS v(old_gid, new_gid)
 WHERE m."_gpay_id" = v.old_gid::bigint;
SELECT COUNT(*) AS active_master_rows FROM master_bidv_connector_service.bank_requests WHERE NOT COALESCE(_deleted, false);
ROLLBACK;
